import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
REBALANCE_DAYS = 10
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
_last_decision = None


def _ensemble():
    p = Path(__file__).parent / "factors" / "factor_ensemble.json"
    obj = json.loads(p.read_text())
    selected = obj.get("selected_factors", [])[:10]
    # Preserve the screener's exact IDs, weights, and directions.
    return selected


def _rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def _bounded(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    # Iterative projection onto the simplex with simple portfolio bounds.
    for _ in range(30):
        total = sum(w.values())
        w = {s: v / total for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_WEIGHT]
        high = [s for s in UNIVERSE if w[s] > MAX_WEIGHT]
        if not low and not high:
            break
        fixed = {s: MIN_WEIGHT for s in low}
        fixed.update({s: MAX_WEIGHT for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        remaining = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, remaining * w[s] / base) for s in UNIVERSE}
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    try:
        selected = _ensemble()
    except Exception:
        return
    if not selected:
        return
    factor_weights = {str(x["factor_id"]): float(x["weight"]) for x in selected}
    factor_dirs = {str(x["factor_id"]): float(x.get("direction", 1)) for x in selected}
    account = get_account_dict()
    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 65:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        volume = np.asarray(df["volume"], dtype=float) if "volume" in df else np.ones(len(close))
        data[symbol] = (close, high, low, ret, volume, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    decision_date = max(v[5] for v in data.values())
    if _last_decision is not None:
        try:
            elapsed = (np.datetime64(decision_date) - np.datetime64(_last_decision)) / np.timedelta64(1, "D")
            if elapsed < REBALANCE_DAYS:
                return
        except Exception:
            return

    trend, clv, leadlag, reversal, riskmom, contrarian = ({}, {}, {}, {}, {}, {})
    invvol = {}
    five_day = {}
    for symbol, (c, h, l, r, vol, _) in data.items():
        v20 = max(float(np.std(r[-20:])), 0.008)
        invvol[symbol] = 1.0 / v20
        five_day[symbol] = c[-1] / max(c[-6], 1e-12) - 1.0
        trend[symbol] = (c[-1] / c[-21] - 1.0) - 0.5 * (c[-1] / c[-61] - 1.0)
        clv[symbol] = (2.0 * c[-1] - h[-1] - l[-1]) / max(h[-1] - l[-1], 1e-12)
        reversal[symbol] = -float(np.mean(r[-5:]))
        riskmom[symbol] = float((c[-1] / c[-21] - 1.0) / (v20 + 0.01))
        volume_ratio = float(np.mean(vol[-5:]) / max(np.mean(vol[-20:]), 1e-12))
        contrarian[symbol] = -float(np.mean(r[-5:])) * min(volume_ratio, 2.0)
    median5 = float(np.median(list(five_day.values())))
    leadlag = {s: five_day[s] - median5 for s in five_day}
    signals = {
        "miner_2_trend_acceleration_20_60": trend,
        "miner_3_clv_1d": clv,
        "peer_median_leadlag_5d": leadlag,
        "short_term_reversal_5d": reversal,
        "miner_2_risk_adjusted_momentum_20d": riskmom,
        "volume_confirmed_contrarian_5d": contrarian,
    }
    ranks = {fid: _rank(signals.get(fid, {})) for fid in factor_weights}
    score = {s: sum(factor_weights[f] * factor_dirs[f] * ranks[f].get(s, 0.5) for f in factor_weights) for s in UNIVERSE}

    # Medium-high risk / sideways regime: retain full investment but favor defensives
    # when the broad market is below its 20-day trend.
    if "SPX" in data and data["SPX"][0][-1] < data["SPX"][0][-21]:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.14
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.07
    mean_inv = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], 0.01) * (0.78 + 0.22 * invvol.get(s, mean_inv) / max(mean_inv, 1e-12)) for s in UNIVERSE}
    weights = _bounded(raw)
    mean_score = float(np.mean(list(score.values())))
    sd_score = max(float(np.std(list(score.values()))), 1e-12)
    # Deterministic 10-day proxy used solely by the migration-cost gate.
    forecast_returns = {s: float(0.01 * (score[s] - mean_score) / sd_score) for s in UNIVERSE}
    rebalance_to_weights(
        weights,
        forecast_returns=forecast_returns,
        factor_ids=list(factor_weights),
        horizon_days=10,
    )
    _last_decision = decision_date

