UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {"miner_2_trend_acceleration_20_60": .22, "miner_3_clv_1d": .21, "peer_median_leadlag_5d": .19, "short_term_reversal_5d": .15, "miner_2_risk_adjusted_momentum_20d": .14, "volume_confirmed_contrarian_5d": .09}
MIN_W, MAX_W, REBALANCE_DAYS = .015, .16, 10
last_date = None

def rank(x):
    out = {s: .5 for s in UNIVERSE}; good = sorted((s, float(v)) for s, v in x.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good): out[s] = (i + 1.) / len(good)
    return out

def box_weights(raw):
    w = {s: max(1e-9, float(raw.get(s, 0))) for s in UNIVERSE}
    for _ in range(20):
        z = sum(w.values()); w = {s: v / z for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < MIN_W]; high = [s for s in UNIVERSE if w[s] > MAX_W]
        if not low and not high: break
        fixed = {s: MIN_W for s in low}; fixed.update({s: MAX_W for s in high})
        free = [s for s in UNIVERSE if s not in fixed]; rem = 1. - sum(fixed.values()); base = sum(w[s] for s in free) or 1.
        w = {s: fixed.get(s, rem * w[s] / base) for s in UNIVERSE}
    z = sum(w.values()); return {s: float(w[s] / z) for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict(); data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=100)
