        remaining = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free) or 1.0
        w = {s: fixed.get(s, remaining * w[s] / base) for s in UNIVERSE}
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    try:
        selected = _selected()
    except Exception:
        return
    if not selected:
        return
    fw = {x["factor_id"]: float(x["weight"]) for x in selected}
    fd = {x["factor_id"]: float(x.get("direction", 1)) for x in selected}
