def _rank(vals):
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def _bounded(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    for _ in range(100):
        fixed = {s: MIN_WEIGHT for s in UNIVERSE if w[s] < MIN_WEIGHT}
        fixed.update({s: MAX_WEIGHT for s in UNIVERSE if w[s] > MAX_WEIGHT})
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free) or 1.0
        nw = {s: fixed.get(s, rem * w[s] / base) for s in UNIVERSE}
        if max(abs(nw[s] - w[s]) for s in UNIVERSE) < 1e-10:
