import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
_last_decision = None


def _ensemble():
    p = Path(__file__).parent / "factors" / "factor_ensemble.json"
    try:
        x = json.loads(p.read_text()).get("selected_factors", [])
        return {z["factor_id"]: z for z in x[:10]}
    except Exception:
        return {}


def _rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def _simplex(raw):
    # Full investment with modest concentration caps; no cash sleeve.
    w = {s: max(float(raw.get(s, 0.01)), 1e-9) for s in UNIVERSE}
    for _ in range(20):
        lo = {s for s in UNIVERSE if w[s] < MIN_WEIGHT}
        hi = {s for s in UNIVERSE if w[s] > MAX_WEIGHT}
        free = [s for s in UNIVERSE if s not in lo and s not in hi]
        remain = 1 - MIN_WEIGHT * len(lo) - MAX_WEIGHT * len(hi)
        den = sum(w[s] for s in free) or 1
        w = {s: MIN_WEIGHT if s in lo else MAX_WEIGHT if s in hi else remain*w[s]/den for s in UNIVERSE}
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    specs = _ensemble()
    if not specs:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=150)
        if df is None or len(df) < 80:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)
        o = np.asarray(df["open"], float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1
        data[s] = (c, o, r, str(df.iloc[-1]["date"]))
    if len(data) < 12:
        return
    date = max(x[3] for x in data.values())
    if _last_decision is not None:
        # ten completed observations are represented conservatively by a
        # ten-calendar-day gate; the execution helper remains authoritative.
        try:
            if (np.datetime64(date)-np.datetime64(_last_decision))/np.timedelta64(1, "D") < 10:
                return
        except Exception:
            return

    vol, r10, r20, trend, recovery, down20, down10, gap, rng = ({},)*9
    for s, (c, o, r, _) in data.items():
        vol[s] = max(float(np.std(r[-20:])), .008)
        r10[s] = c[-1] / max(c[-11], 1e-12) - 1
        r20[s] = c[-1] / max(c[-21], 1e-12) - 1
        r60 = c[-1] / max(c[-61], 1e-12) - 1
        trend[s] = r20[s] - r60 / 3.0
        trough = max(float(np.min(c[-61:-1])), 1e-12)
        recovery[s] = (c[-1]/trough - 1) / (1 + vol[s])
        neg = r[-20:][r[-20:] < 0]
        down20[s] = float(np.std(neg)) if len(neg) > 1 else vol[s]
        neg10 = r[-10:][r[-10:] < 0]
        down10[s] = float(np.std(neg10)) if len(neg10) > 1 else vol[s]
        gaps = o[1:] / np.maximum(c[:-1], 1e-12) - 1
        gap[s] = -float(np.mean(gaps[-4:-1])) if len(gaps) >= 4 else 0
        lo, hi = np.min(c[-21:-1]), np.max(c[-21:-1])
        rng[s] = .5 - (c[-1]-lo)/max(hi-lo, 1e-12)

    med20 = float(np.median(list(r20.values())))
    tape = float(np.median(list(r20.values())))
    raw = {}
    for s in data:
        raw[s] = {
            "miner_1_20280824_gap_reversal_10d": gap[s],
            "miner_1_low_volatility_20d": -vol[s],
            "miner_2_20280810_downside_vol_reversal_20d": -r20[s] * (.5 + down20[s]/vol[s]),
            "miner_3_drawdown_recovery_20d": recovery[s],
            "miner_3_vol_scaled_relative_contrarian_20d": -(r20[s]-med20)/vol[s],
            "miner_2_trend_acceleration_20_60": trend[s],
            "miner_2_20280824_downside_vol_reversal_10d": -r10[s] * (.5 + down10[s]/vol[s]),
            "trend_conditioned_range_reversal_10d": rng[s] * (.5 + .5*float(tape > -.01)),
        }
    ranks = {f: _rank({s: raw[s][f] for s in data}) for f in specs}
    score = {s: sum(specs[f]["weight"]*specs[f].get("direction", 1)*ranks[f][s] for f in specs) for s in UNIVERSE}
    breadth = np.mean([r20[s] > 0 for s in data])
    if r20.get("SPX", 0) < 0 and breadth < .55:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .10
        for s in ("BTC", "ETH", "WTI"): score[s] -= .06
    avgvol = np.mean(list(vol.values()))
    weights = _simplex({s: max(score[s], .01) * (.85 + .15*avgvol/vol.get(s, avgvol)) for s in UNIVERSE})
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(.008*(score[s]-mu)/sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=list(specs), horizon_days=10)
    _last_decision = date

