UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
_last_decision = None


def load_ensemble():
    try:
        data = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        rows = data.get("selected_factors", [])[:10]
        return {r["factor_id"]: {"weight": float(r["weight"]), "direction": int(r.get("direction", 1))} for r in rows}
    except Exception:
        return {}


def cross_rank(x):
    good = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    return out


def simplex(raw):
