        high = {s for s in UNIVERSE if w[s] > MAX_WEIGHT}
        free = [s for s in UNIVERSE if s not in low and s not in high]
        rem = 1.0 - MIN_WEIGHT * len(low) - MAX_WEIGHT * len(high)
        scale = rem / max(sum(w[s] for s in free), 1e-12)
        w = {s: MIN_WEIGHT if s in low else MAX_WEIGHT if s in high else w[s] * scale for s in UNIVERSE}
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    specs = load_ensemble()
    if not specs:
        return

    series = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=170)
        if df is not None and len(df) >= 80:
