import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
_last_decision = None


def load_factors():
    try:
        p = Path(__file__).parent / "factor_ensemble.json"
        return json.loads(p.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(len(good), 1)
    return out


def project(raw):
    # Simple bounded simplex projection for a fully invested 15-asset book.
    w = {s: max(float(raw.get(s, 0.01)), 1e-9) for s in UNIVERSE}
    fixed = {}
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        scale = (1.0 - sum(fixed.values())) / max(sum(w[s] for s in free), 1e-12)
        changed = False
        for s in free:
            x = w[s] * scale
            if x < MIN_WEIGHT:
                fixed[s] = MIN_WEIGHT; changed = True
            elif x > MAX_WEIGHT:
                fixed[s] = MAX_WEIGHT; changed = True
        if not changed:
            for s in free:
                w[s] = w[s] * scale
            break
    w.update(fixed)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    factors = load_factors()
    if not factors:
        return
    ids = {f["factor_id"] for f in factors}
    features = {fid: {} for fid in ids}
    vol, ten_day, dates = {}, {}, []
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=190)
        if df is None or len(df) < 85:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v20, v60 = max(np.std(r[-20:]), .008), max(np.std(r[-60:]), .008)
        a10, a20, a40, a60 = c[-1]/c[-11]-1, c[-1]/c[-21]-1, c[-1]/c[-41]-1, c[-1]/c[-61]-1
        downside = max(np.std(np.minimum(r[-20:], 0)), .008)
        vol[symbol], ten_day[symbol] = float(v20), float(a10)
        dates.append(df.iloc[-1]["date"])
        raw = {
            "vol_adjusted_trend_acceleration_10d": (a10 - a20/2) / v20,
            "miner_1_low_volatility_20d": -v20,
