        if "miner_3_residual_contrarian_10d" in ids:
            features["miner_3_residual_contrarian_10d"][s] = residual
    date_key = str(max(dates))
    if _last_decision is not None:
        try:
            if (np.datetime64(date_key) - np.datetime64(_last_decision)) / np.timedelta64(1, "D") < 10:
                return
