    if ten_day.get("SPX", 0) < 0 or breadth < .40:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .10
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .05
    avg_vol = max(float(np.mean(list(vol.values()))), .008)
    raw = {s: max(score[s], .01) * (.85 + .15 * avg_vol / max(vol[s], .008)) for s in UNIVERSE}
