MIN_W, MAX_W = 0.015, 0.16
_last_date = None


def load_factors():
    try:
        fs = json.loads((Path(__file__).parent / "factor_ensemble.json").read_text()).get("selected_factors", [])
        return fs[:10]
    except Exception:
        return []


def rank(values):
    out = {s: 0.5 for s in UNIVERSE}
    finite = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for k, (s, _) in enumerate(finite):
        out[s] = (k + 1) / max(len(finite), 1)
    return out


def bounded_simplex(raw):
    # Bounded projection preserves full investment and representation of every asset.
    w = {s: max(float(raw.get(s, 0.01)), 1e-10) for s in UNIVERSE}
    fixed = {}
    for _ in range(50):
        free = [s for s in UNIVERSE if s not in fixed]
        remaining = 1.0 - sum(fixed.values())
        scale = remaining / max(sum(w[s] for s in free), 1e-12)
        clipped = False
        for s in free:
            q = w[s] * scale
            if q < MIN_W:
                fixed[s] = MIN_W; clipped = True
            elif q > MAX_W:
                fixed[s] = MAX_W; clipped = True
