import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.16
_last_date = None


def load_factors():
    try:
        return json.loads((Path(__file__).parent / "factor_ensemble.json").read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(vals):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1) / max(1, len(good))
    return out


def bound_weights(raw):
    w = {s: max(float(raw.get(s, 0.01)), 1e-8) for s in UNIVERSE}
    # Iterative water filling preserves a complete, long-only target.
    for _ in range(20):
        fixed = {s for s in UNIVERSE if w[s] < MIN_W or w[s] > MAX_W}
        for s in fixed:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        if not free:
            break
        total = sum(w[s] for s in free)
        for s in free:
            w[s] *= rem / total
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_date
    factors = load_factors()
    if not factors:
        return
    ids = [f["factor_id"] for f in factors]
    vals = {fid: {} for fid in ids}
    closes, vol20, ret10, dates = {}, {}, {}, []
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=220)
        if df is None or len(df) < 70:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.008)
        v60 = max(float(np.std(r[-60:])), 0.008)
        a5, a10, a20, a60 = c[-1]/c[-6]-1, c[-1]/c[-11]-1, c[-1]/c[-21]-1, c[-61]/c[-1]-1
        # Values are lagged to the last completed bar supplied by the API.
        raw = {
            "vol_adjusted_trend_acceleration_10d": (a10 - 0.5*a20) / v20,
            "miner_2_20290531_robust_breadth_trend_10d": a10 / v20,
            "miner_1_low_volatility_20d": -v20,
            "miner_2_trend_acceleration_20_60": (a20 + a60/3) / v60,
            "miner_2_20290726_semivolatility_recovery_10d": (a10 / max(v20, 0.008)) * (1.0 + max(0.0, a10)),
        }
        closes[s], vol20[s], ret10[s] = c, v20, a10
        dates.append(df.iloc[-1]["date"])
        for fid in ids:
            if fid in raw:
                vals[fid][s] = raw[fid]
    if len(closes) < 12:
        return
    if "peer_median_leadlag_5d" in vals:
        for s, c in closes.items():
            own = c[-1] / c[-6] - 1
            peers = [x[-1] / x[-6] - 1 for t, x in closes.items() if t != s]
            vals["peer_median_leadlag_5d"][s] = own - float(np.median(peers))
    rr = {fid: ranks(vals[fid]) for fid in ids}
    score = {s: sum(float(f["weight"]) * int(f.get("direction", 1)) * rr[f["factor_id"]][s] for f in factors) for s in UNIVERSE}
    breadth = float(np.mean([x > 0 for x in ret10.values()]))
    high_risk = breadth < 0.55 or ret10.get("SPX", 0.0) < 0.0
    if high_risk:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.15
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.08
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-9)
    forecast = {s: float(0.008 * (score[s] - mean) / sd) for s in UNIVERSE}
    avgv = max(float(np.mean(list(vol20.values()))), 0.008)
    raww = {s: max(score[s], 0.01) * (0.85 + 0.15 * avgv / max(vol20.get(s, avgv), 0.008)) for s in UNIVERSE}
    weights = bound_weights(raww)
    d = str(max(dates))
    if _last_date is not None:
        try:
            if (np.datetime64(d) - np.datetime64(_last_date)) / np.timedelta64(1, "D") < 10:
                return
        except Exception:
            return
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _last_date = d

