import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.16
_last_decision = None


def load_factors():
    p = Path(__file__).parent / "factors" / "factor_ensemble.json"
    try:
        x = json.loads(p.read_text())
        return x.get("selected_factors", [])[:10]
    except Exception:
        return []


def rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(1, len(good))
    return out


def bounded(raw):
    # Projection onto the complete simplex with conservative per-asset bounds.
    w = {s: max(1e-12, float(raw.get(s, 0.0))) for s in UNIVERSE}
    for _ in range(30):
        lo = {s for s in UNIVERSE if w[s] < MIN_W}
        hi = {s for s in UNIVERSE if w[s] > MAX_W}
        for s in lo: w[s] = MIN_W
        for s in hi: w[s] = MAX_W
        fixed = lo | hi
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        if not free or rem <= 0: break
        z = sum(w[s] for s in free)
        for s in free: w[s] *= rem / z
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision
    factors = load_factors()
    if not factors:
        return
    ids = [str(f["factor_id"]) for f in factors]
    panels = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=230)
        if df is None or len(df) < 70:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        if len(c) < 65 or np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        panels[s] = c
    if len(panels) < 12:
        return

    # Use the common trailing date. All values are therefore observable at the
    # decision and the one-day lag is represented by using bars ending at -2.
    end = min(len(c) for c in panels.values()) - 2
    if end < 64:
        return
    returns = {s: panels[s][1:end+2] / panels[s][:end+1] - 1.0 for s in panels}
    r20 = {s: panels[s][end] / panels[s][end-20] - 1.0 for s in panels}
    median20 = float(np.median(list(r20.values())))
    vol20 = {s: max(float(np.std(returns[s][end-20:end])), 0.008) for s in panels}

    raw = {fid: {} for fid in ids}
    breadth = []
    # Cross-sectional positive-return breadth used by the reversal factor.
    for k in (end-2, end-1, end):
        breadth.append(float(np.mean([panels[s][k] / panels[s][k-20] - 1.0 > 0 for s in panels])))
    for s, c in panels.items():
        rr = returns[s]
        neg = np.minimum(rr, 0.0)
        down40 = max(float(np.std(neg[end-40:end])), 0.008)
        # smoothed, lagged 20-day downside-vol reversal
        rev_hist = []
        for k in (end-4, end-3, end-2):
            if k < 40: continue
            x = c[k] / c[k-20] - 1.0
            b = float(np.mean([panels[t][k] / panels[t][k-20] - 1.0 > 0 for t in panels]))
            dn = max(float(np.std(np.minimum(returns[s][k-40:k], 0.0))), 0.008)
            rev_hist.append((-x / dn) * (abs(b - 0.5) + 0.5))
        rev = float(np.mean(rev_hist)) if rev_hist else 0.0
        # Semivolatility recovery: relative weakness plus recent impulse.
        rel = (c[end] / c[end-20] - 1.0) - median20
        recovery = (c[end] / c[end-5] - 1.0) - (c[end-5] / c[end-20] - 1.0)
        down30 = max(float(np.std(np.minimum(rr[end-30:end], 0.0))), 0.008)
        semi = (-rel / vol20[s]) + (recovery / vol20[s]) * (down30 / vol20[s])
        raw.setdefault("miner_2_20280810_downside_vol_reversal_20d", {})[s] = rev
        raw.setdefault("miner_1_20280224_low_volatility_20d", {})[s] = -vol20[s]
        raw.setdefault("miner_2_20290726_semivolatility_recovery_10d", {})[s] = semi

    scores = {s: 0.0 for s in UNIVERSE}
    for f in factors:
        fid = f["factor_id"]
        rr = rank(raw.get(fid, {}))
        for s in UNIVERSE:
            scores[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]
    breadth10 = np.mean([panels[s][end] / panels[s][end-10] - 1 > 0 for s in panels])
    high_risk = breadth10 < 0.55 or panels["SPX"][end] / panels["SPX"][end-10] - 1 < 0
    if high_risk:
        for s in ("XAU", "US10Y", "CN10Y"): scores[s] += 0.15
        for s in ("BTC", "ETH", "WTI"): scores[s] -= 0.08
    mean, sd = np.mean(list(scores.values())), max(np.std(list(scores.values())), 1e-9)
    forecast = {s: float(0.008 * (scores[s] - mean) / sd) for s in UNIVERSE}
    avgvol = float(np.mean(list(vol20.values())))
    raww = {s: max(scores[s], 0.01) * (0.85 + 0.15 * avgvol / vol20.get(s, avgvol)) for s in UNIVERSE}
    weights = bounded(raww)
    # Rebalance only once per ten-trading-day block.
    stamp = str(end)
    if _last_decision is not None and end - _last_decision < 10:
        return
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    _last_decision = end

