import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.16
_last_end = None


def ensemble():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        return json.loads(p.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def ranks(x):
    out = {s: 0.5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in x.items() if np.isfinite(v))
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.) / len(a)
    return out


def bounded_simplex(raw):
    # Water-fill onto the full-investment simplex with explicit bounds.
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    free = set(UNIVERSE)
    fixed = {}
    for _ in range(100):
        z = sum(w[s] for s in free)
        rem = 1.0 - sum(fixed.values())
        if not free:
            break
        for s in free:
            w[s] *= rem / max(z, 1e-12)
        low = [s for s in free if w[s] < MIN_W]
        high = [s for s in free if w[s] > MAX_W]
        if not low and not high:
            break
        for s in low:
            fixed[s] = MIN_W
            free.remove(s)
        for s in high:
            fixed[s] = MAX_W
            free.remove(s)
    out = dict(fixed)
    if free:
        z = sum(w[s] for s in free)
        rem = 1.0 - sum(fixed.values())
        out.update({s: rem * w[s] / max(z, 1e-12) for s in free})
    return {s: float(out.get(s, MIN_W)) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_end
    fs = ensemble()
    if not fs or {str(f.get("factor_id")) for f in fs} != {
        "miner_3_defensive_volatility_quality_10d",
        "miner_3_dxy_conditioned_momentum_10d",
        "miner_3_downside_asymmetry_reversal_10d",
        "miner_2_inefficient_trend_reversal_10d",
        "miner_3_dispersion_conditioned_reversal_10d",
    }:
        return
    panels = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=260)
        if d is not None and len(d) >= 150:
            c = np.asarray(d.sort_values("date")["close"], dtype=float)
            if np.all(np.isfinite(c)) and np.all(c > 0):
                panels[s] = c
    if len(panels) < 12:
        return
    end = min(len(x) for x in panels.values()) - 2
    if end < 125 or (_last_end is not None and end - _last_end < 10):
        return

    # DXY is observation-only and is used solely as a conditioning signal.
    dxy_ret = 0.0
    try:
        dx = get_index_daily_data(symbol="DXY", days=30)
        if dx is not None and len(dx) >= 12:
            q = np.asarray(dx.sort_values("date")["close"], dtype=float)
            dxy_ret = float(q[-2] / q[-12] - 1.)
    except Exception:
        pass
    sig = {str(f["factor_id"]): {} for f in fs}
    for s, c in panels.items():
        r = c[1:] / c[:-1] - 1.
        v10 = max(float(np.std(r[end-10:end])), .008)
        v20 = max(float(np.std(r[end-20:end])), .008)
        lv = max(float(np.median([np.std(r[k-20:k]) for k in range(end-100, end)])), .008)
        mom10 = c[end] / c[end-10] - 1.
        mom20 = c[end] / c[end-20] - 1.
        sig["miner_3_defensive_volatility_quality_10d"][s] = -(v20 / lv) - .25 * max(0., v10 / v20 - 1.)
        sig["miner_3_dxy_conditioned_momentum_10d"][s] = mom20 * (1.0 + np.sign(dxy_ret) * .25)
        downside = max(float(np.std(np.minimum(r[end-20:end], 0))), .008)
        sig["miner_3_downside_asymmetry_reversal_10d"][s] = -mom20 / downside
        sig["miner_2_inefficient_trend_reversal_10d"][s] = -mom10 / v10
        sig["miner_3_dispersion_conditioned_reversal_10d"][s] = -mom10 / max(v10, lv)

    score = {s: 0.0 for s in UNIVERSE}
    for f in fs:
        rr = ranks(sig[str(f["factor_id"])])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]
    breadth = np.mean([panels[s][end] / panels[s][end-60] - 1. > 0 for s in panels])
    spx20 = panels.get("SPX", panels[next(iter(panels))])[end] / panels.get("SPX", panels[next(iter(panels))])[end-20] - 1.
    if breadth < .55 or spx20 < 0:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .16
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .08
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.006 * (score[s] - mean) / sd) for s in UNIVERSE}
    floor = min(score.values())
    weights = bounded_simplex({s: max(.01, score[s] - floor + .05) for s in UNIVERSE})
    rebalance_to_weights(weights, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in fs], horizon_days=10)
    _last_end = end

