import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.16
_last_decision_end = None


def load_ensemble():
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        return json.loads(p.read_text()).get("selected_factors", [])[:10]
    except Exception:
        return []


def cross_rank(values):
    valid = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    valid.sort(key=lambda z: z[1])
    out = {s: 0.5 for s in UNIVERSE}
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / max(n, 1)
    return out


def bounded_weights(scores):
    # Deterministic projection to the required full-investment simplex.
    raw = {s: max(float(scores.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    fixed, free = {}, set(UNIVERSE)
    for _ in range(30):
        remain = 1.0 - sum(fixed.values())
        z = sum(raw[s] for s in free)
        for s in free:
            raw[s] = raw[s] * remain / max(z, 1e-12)
        low = [s for s in free if raw[s] < MIN_W]
        high = [s for s in free if raw[s] > MAX_W]
        if not low and not high:
            break
        for s in low:
            fixed[s] = MIN_W
            free.remove(s)
        for s in high:
            fixed[s] = MAX_W
            free.remove(s)
    remain = 1.0 - sum(fixed.values())
    z = sum(raw[s] for s in free)
    fixed.update({s: remain * raw[s] / max(z, 1e-12) for s in free})
    # Correct tiny floating point drift without changing the asset set.
    total = sum(fixed.values())
    return {s: float(fixed[s] / total) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _last_decision_end
    fs = load_ensemble()
    if not fs or len(fs) > 10:
        return
    factor_ids = [str(f["factor_id"]) for f in fs]
    required = {
        "miner_3_defensive_volatility_quality_10d",
        "miner_1_20291129_vix80_binary_reversal_10d",
        "miner_3_downside_asymmetry_reversal_10d",
        "miner_2_inefficient_trend_reversal_10d",
        "miner_3_dispersion_conditioned_reversal_10d",
        "miner_3_vix_conditioned_reversal_10d",
    }
    if set(factor_ids) != required:
        return

    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 130:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) >= 130 and np.all(np.isfinite(c)) and np.all(c > 0):
            closes[symbol] = c
    if len(closes) < 12:
        return
    end = min(len(c) for c in closes.values()) - 2  # last completed, lagged day
    if end < 110 or (_last_decision_end is not None and end - _last_decision_end < 10):
        return

    # VIX is observation-only. It gates stress reversal signals; it is never ordered.
    vix = 0.0
    try:
        vd = get_index_daily_data(symbol="VIX", days=30)
        if vd is not None and len(vd) >= 2:
            vix = float(vd.sort_values("date")["close"].iloc[-2])
    except Exception:
        pass
    stress80 = 1.0 if vix >= 80.0 else 0.0
    stress = min(max(vix / 40.0, 0.0), 2.0)

    signals = {f: {} for f in factor_ids}
    for s, c in closes.items():
        r = c[1:] / c[:-1] - 1.0
        v10 = max(float(np.std(r[end-10:end])), 0.008)
        v20 = max(float(np.std(r[end-20:end])), 0.008)
        base_vol = max(float(np.median([np.std(r[k-20:k]) for k in range(end-80, end)])), 0.008)
        mom10 = c[end] / c[end-10] - 1.0
        mom20 = c[end] / c[end-20] - 1.0
        down = max(float(np.std(np.minimum(r[end-20:end], 0.0))), 0.008)
        # Positive direction is preserved: higher values rank better.
        signals["miner_3_defensive_volatility_quality_10d"][s] = -(v20 / base_vol) - 0.25 * max(v10 / v20 - 1.0, 0.0)
        signals["miner_1_20291129_vix80_binary_reversal_10d"][s] = stress80 * (-mom10 / v10)
        signals["miner_3_downside_asymmetry_reversal_10d"][s] = -mom20 / down
        signals["miner_2_inefficient_trend_reversal_10d"][s] = -mom10 / v10
        signals["miner_3_dispersion_conditioned_reversal_10d"][s] = -mom10 / max(v10, base_vol)
        signals["miner_3_vix_conditioned_reversal_10d"][s] = -mom10 / v10 * stress

    score = {s: 0.0 for s in UNIVERSE}
    for f in fs:
        rr = cross_rank(signals[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]

    # High-risk rebound: keep full investment but explicitly support defensives.
    ref = closes.get("SPX", next(iter(closes.values())))
    breadth = np.mean([closes[s][end] / closes[s][end-60] - 1.0 > 0 for s in closes])
    if breadth < 0.55 or ref[end] / ref[end-20] - 1.0 < 0 or vix >= 30:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.06

    mean = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.006 * (score[s] - mean) / sd) for s in UNIVERSE}
    floor = min(score.values())
    weights = bounded_weights({s: score[s] - floor + 0.05 for s in UNIVERSE})
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    _last_decision_end = end

