UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_W, MAX_W = 0.015, 0.16
last_end = -999


def ensemble():
    for p in (Path(__file__).parent / "factor_ensemble.json", Path(__file__).parent / "factors" / "factor_ensemble.json"):
        try:
            fs = json.loads(p.read_text()).get("selected_factors", [])
            if fs and len(fs) <= 10:
                return fs
        except Exception:
            pass
    return []


def ranks(values):
    out = {s: 0.5 for s in UNIVERSE}
    good = sorted([(s, v) for s, v in values.items() if np.isfinite(v)], key=lambda z: z[1])
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(1, len(good))
    return out


def capped_weights(score):
    # Projection to a complete, long-only, full-investment target.
    w = {s: max(1e-8, float(score[s])) for s in UNIVERSE}
    fixed, free = {}, set(UNIVERSE)
    for _ in range(20):
        rem = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(z, 1e-12)
        lo = [s for s in free if w[s] < MIN_W]
        hi = [s for s in free if w[s] > MAX_W]
        if not lo and not hi:
            break
        for s in lo:
            fixed[s] = MIN_W; free.remove(s)
        for s in hi:
            fixed[s] = MAX_W; free.remove(s)
    rem = 1.0 - sum(fixed.values())
    z = sum(w[s] for s in free)
    fixed.update({s: rem * w[s] / max(z, 1e-12) for s in free})
    z = sum(fixed.values())
    return {s: fixed[s] / z for s in UNIVERSE}


@register_hook
def strategy():
    global last_end
    fs = ensemble()
    if not fs:
        return
    ids = [str(f["factor_id"]) for f in fs]
    closes = {}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=270)
        if d is None or len(d) < 130:
            continue
        c = np.asarray(d.sort_values("date")["close"], dtype=float)
        if np.all(np.isfinite(c)) and np.all(c > 0):
            closes[s] = c
    if len(closes) < 10:
        return
    end = min(len(c) for c in closes.values()) - 2
    if end < 100 or end - last_end < 10:
        return

    vix = 0.0
    try:
        d = get_index_daily_data(symbol="VIX", days=40)
        if d is not None and len(d) >= 2:
            vix = float(d.sort_values("date")["close"].iloc[-2])
    except Exception:
        pass

    sig = {f["factor_id"]: {} for f in fs}
    for s, c in closes.items():
        r = c[1:] / c[:-1] - 1.0
        v10 = max(np.std(r[end-10:end]), 0.008)
        v20 = max(np.std(r[end-20:end]), 0.008)
        hist = [np.std(r[k-20:k]) for k in range(max(25, end-80), end)]
        base = max(np.median(hist), 0.008)
        m10, m20 = c[end] / c[end-10] - 1.0, c[end] / c[end-20] - 1.0
        down = max(np.std(np.minimum(r[end-20:end], 0)), 0.008)
        vals = {
            "miner_3_defensive_volatility_quality_10d": -(v20 / base) - 0.25 * max(v10 / v20 - 1, 0),
            "miner_1_20291129_vix80_binary_reversal_10d": (-m10 / v10) if vix >= 80 else 0.0,
            "miner_3_tailrisk_reversal_10d": -m10 / v10,
            "miner_3_downside_asymmetry_reversal_10d": -m20 / down,
            "miner_2_20291101_inefficient_trend_reversal_10d": -m10 / v10,
            "miner_3_vix_conditioned_reversal_10d": (-m10 / v10) if vix >= 30 else 0.0,
        }
        for f in ids:
            sig[f][s] = vals.get(f, 0.0)

    score = {s: 0.0 for s in UNIVERSE}
    for f in fs:
        rr = ranks(sig[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]

    breadth = np.mean([closes[s][end] / closes[s][end-60] - 1 > 0 for s in closes])
    if vix >= 30 or breadth < 0.55:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.06
    floor = min(score.values())
    target = capped_weights({s: score[s] - floor + 0.05 for s in UNIVERSE})
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(0.006 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_end = end

