MIN_W, MAX_W = 0.015, 0.16
last_end = -999


def load_ensemble():
    try:
        x = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        fs = x.get("selected_factors", [])
        return fs if fs and len(fs) <= 10 else []
    except Exception:
        return []


def rank(vals):
    out = {s: .5 for s in UNIVERSE}
    a = sorted((s, v) for s, v in vals.items() if np.isfinite(v))
    n = len(a)
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1) / max(n, 1)
    return out


def project(raw):
    # Iterative bounded simplex projection; all 15 names remain invested.
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    fixed = {}
    free = set(UNIVERSE)
    for _ in range(20):
        rem = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(z, 1e-12)
        low = [s for s in free if w[s] < MIN_W]
        high = [s for s in free if w[s] > MAX_W]
        if not low and not high:
            break
        for s in low:
            fixed[s] = MIN_W; free.remove(s)
        for s in high:
            fixed[s] = MAX_W; free.remove(s)
    rem, z = 1.0 - sum(fixed.values()), sum(w[s] for s in free)
    fixed.update({s: rem * w[s] / max(z, 1e-12) for s in free})
    z = sum(fixed.values())
    return {s: fixed[s] / z for s in UNIVERSE}


