        v20 = max(np.std(r[end-20:end]), .008)
        hist = [np.std(r[k-20:k]) for k in range(max(25, end-80), end)]
        baseline = max(np.median(hist), .008)
        m10, m20 = c[end] / c[end-10] - 1, c[end] / c[end-20] - 1
        downside = max(np.std(np.minimum(r[end-20:end], 0)), .008)
        # Relative residual and cross-sectional dispersion are stable, bounded proxies.
        peer = np.mean([rets[q][end-10:end] for q in rets if len(rets[q]) > end], axis=0)
        residual = np.mean(r[end-10:end] - peer)
        raw = {
            "miner_3_defensive_volatility_quality_10d": -(v20 / baseline) - .25 * max(v10 / v20 - 1, 0),
