            "miner_3_dispersion_conditioned_reversal_10d": (-residual / v10) * (1 + min(np.std([rets[q][end-10:end] for q in rets]), 2.0)),
        }
        for f in fs:
            vals[f["factor_id"]][s] = raw.get(f["factor_id"], 0.0)

    score = {s: 0.0 for s in UNIVERSE}
    for f in fs:
        rr = rank(vals[f["factor_id"]])
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * int(f.get("direction", 1)) * rr[s]
    breadth = np.mean([closes[s][end] / closes[s][end-60] > 1 for s in closes])
    if vix >= 30 or breadth < .55:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .12
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= .06
    floor = min(score.values())
    target = project({s: score[s] - floor + .05 for s in UNIVERSE})
    mu, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.006 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast, factor_ids=ids, horizon_days=10)
    last_end = end

