import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_stock_daily_data, get_index_daily_data,
    rebalance_to_weights,
)

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
MIN_WEIGHT, MAX_WEIGHT = 0.015, 0.16
last_decision_end = -10**9


def load_ensemble():
    try:
        data = json.loads((Path(__file__).parent / "factor_ensemble.json").read_text())
        factors = data.get("selected_factors", [])
        return factors if 0 < len(factors) <= 10 else []
    except Exception:
        return []


def percentile_rank(values):
    result = {s: 0.5 for s in UNIVERSE}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    for i, (s, _) in enumerate(valid):
        result[s] = (i + 1.0) / max(len(valid), 1)
    return result


def bounded_simplex(raw):
    # Preserve a complete, long-only, fully invested 15-asset target.
    w = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    fixed = {}
    free = set(UNIVERSE)
    for _ in range(20):
        remain = 1.0 - sum(fixed.values())
        total = sum(w[s] for s in free)
        for s in free:
