UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = [
    ("miner_1_volatility_compression_10d_v1", 0.29, 1),
    ("miner_3_defensive_volatility_quality_10d", 0.25, 1),
    ("trend_inefficiency_reversal_10d", 0.18, 1),
    ("relative_lowvolatility_10d", 0.12, 1),
    ("relative_residual_reversal_10d", 0.10, 1),
    ("dispersion_gated_reversal_10d", 0.06, 1),
]
last_decision = -10**9

def rank(values):
    good = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out

def bounded(raw):
    lo, hi = .02, .15
    w = {s: raw[s] / max(sum(raw.values()), 1e-12) for s in UNIVERSE}
    for _ in range(50):
        fixed = {s: lo if w[s] < lo else hi for s in UNIVERSE if w[s] < lo or w[s] > hi}
        if not fixed: break
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1 - sum(fixed.values())
        denom = sum(raw[s] for s in free)
        w = dict(fixed)
        for s in free: w[s] = rem * raw[s] / max(denom, 1e-12)
    z = sum(w.values())
    return {s: float(w[s] / z) for s in UNIVERSE}

@register_hook
def strategy():
    global last_decision
    closes = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=320)
        if df is not None and len(df) >= 270:
            c = np.asarray(df.sort_values("date")["close"], dtype=float)
            if np.all(np.isfinite(c)) and np.all(c > 0): closes[s] = c
    if len(closes) < 10: return
    end = min(map(len, closes.values())) - 2  # last completed session, with one-session signal lag
    if end < 260 or end - last_decision < 10: return
    rets = {s: np.diff(np.log(c)) for s, c in closes.items()}
    r10 = {s: rets[s][end-10:end].sum() for s in closes}
    r20 = {s: rets[s][end-20:end].sum() for s in closes}
    v20 = {s: np.std(rets[s][end-20:end]) for s in closes}
    medv = np.median(list(v20.values()))
    # Cross-sectional dispersion gate, calibrated only from historical dates.
    disp_hist = []
    for k in range(end-100, end):
        x = [rets[s][k-10:k].sum() for s in closes if k >= 10]
        if len(x) >= 10: disp_hist.append(np.std(x))
    disp_now = np.std(list(r10.values()))
    gate = bool(disp_hist and disp_now > np.quantile(disp_hist, .60))
    vals = {fid: {} for fid, _, _ in ENSEMBLE}
    for s in closes:
        v10 = max(np.std(rets[s][end-10:end]), .008)
        vv20 = max(v20[s], .008)
        # 40d volatility and its 120d median proxy use trailing completed data.
        v40 = max(np.std(rets[s][end-40:end]), .008)
        series = [np.std(rets[s][j-20:j]) for j in range(end-120, end) if j >= 20]
        vmed = max(np.median(series), .008)
        v20_prev = max(np.std(rets[s][end-30:end-10]), .008)
        vals[ENSEMBLE[0][0]][s] = -(v10 / v40 - 1.0)
        vals[ENSEMBLE[1][0]][s] = -(vv20 / vmed) - .5 * (vv20 / v20_prev - 1.0)
        vals[ENSEMBLE[2][0]][s] = -(r20[s] / max(np.sum(np.abs(rets[s][end-20:end])), .008))
        vals[ENSEMBLE[3][0]][s] = -np.log(vv20 / max(medv, .008))
        vals[ENSEMBLE[4][0]][s] = -(r20[s] - np.median(list(r20.values()))) / vv20
        vals[ENSEMBLE[5][0]][s] = -r10[s] if gate else 0.0
    score = {s: 0.0 for s in UNIVERSE}
    for fid, weight, direction in ENSEMBLE:
        rr = rank(vals[fid])
        for s in UNIVERSE: score[s] += weight * direction * rr[s]
    breadth = np.mean([closes[s][end] > closes[s][end-60] for s in closes])
    if breadth < .55:
        for s in ("XAU", "US10Y", "CN10Y"): score[s] += .10
    floor = min(score.values())
    raw = {s: score[s] - floor + .05 for s in UNIVERSE}
    target = bounded(raw)
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.006 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in ENSEMBLE], horizon_days=10)
    last_decision = end

