import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Exact current Screener ensemble (7 factors, capped below 10).
ENSEMBLE = [
    ("miner_1_volatility_compression_10d_v1", 0.25, 1),
    ("miner_3_defensive_volatility_quality_10d", 0.22, 1),
    ("trend_inefficiency_reversal_10d", 0.16, 1),
    ("relative_lowvolatility_10d", 0.12, 1),
    ("relative_residual_reversal_10d", 0.10, 1),
    ("miner_2_20300822_breadth_conditioned_momentum_10d", 0.10, 1),
    ("miner_1_range_efficiency_reversal_10d_v2", 0.05, 1),
]
last_decision = -10**9

def rank(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out

def bounded(raw):
    # Full investment, long-only, sensible 2%-15% asset bounds.
    lo, hi = 0.02, 0.15
    w = {s: raw[s] / max(sum(raw.values()), 1e-12) for s in UNIVERSE}
    for _ in range(50):
        fixed = {s: (lo if w[s] < lo else hi) for s in UNIVERSE
                 if w[s] < lo or w[s] > hi}
        if not fixed:
            break
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        denom = sum(raw[s] for s in free)
        w = dict(fixed)
        for s in free:
            w[s] = rem * raw[s] / max(denom, 1e-12)
    total = sum(w.values())
    return {s: float(w[s] / total) for s in UNIVERSE}

@register_hook
def strategy():
    global last_decision
    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=340)
        if df is None or len(df) < 270:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) >= 270 and np.all(np.isfinite(c)) and np.all(c > 0):
            closes[symbol] = c
    if len(closes) < 10:
        return
    # Exclude the most recent visible bar: decisions use completed, lagged data.
    end = min(len(c) for c in closes.values()) - 2
    if end < 260 or end - last_decision < 10:
        return
    rets = {s: np.diff(np.log(c)) for s, c in closes.items()}
    r10 = {s: rets[s][end-10:end].sum() for s in closes}
    r20 = {s: rets[s][end-20:end].sum() for s in closes}
    r60 = {s: rets[s][end-60:end].sum() for s in closes}
    v20 = {s: max(np.std(rets[s][end-20:end]), .008) for s in closes}
    medv = np.median(list(v20.values()))
    vals = {fid: {} for fid, _, _ in ENSEMBLE}
    for s in closes:
        v10 = max(np.std(rets[s][end-10:end]), .008)
        v40 = max(np.std(rets[s][end-40:end]), .008)
        prior = max(np.std(rets[s][end-30:end-10]), .008)
        hist = [np.std(rets[s][j-20:j]) for j in range(end-120, end) if j >= 20]
        vmed = max(np.median(hist), .008)
        # Deterministic proxies preserving the submitted factor directions.
        vals[ENSEMBLE[0][0]][s] = -(v10 / v40 - 1.0)                 # compression
        vals[ENSEMBLE[1][0]][s] = -(v20[s] / vmed) - .5*(v20[s]/prior - 1)
        vals[ENSEMBLE[2][0]][s] = -(r20[s] / max(np.sum(np.abs(rets[s][end-20:end])), .008))
        vals[ENSEMBLE[3][0]][s] = -np.log(v20[s] / max(medv, .008))
        vals[ENSEMBLE[4][0]][s] = -(r20[s] - np.median(list(r20.values()))) / v20[s]
        # Breadth-conditioned momentum: neutralize when breadth is weak.
        vals[ENSEMBLE[5][0]][s] = r20[s]
        vals[ENSEMBLE[6][0]][s] = -(r10[s] / max(np.sum(np.abs(rets[s][end-10:end])), .008))
    breadth = np.mean([r60[s] > 0 for s in closes])
    if breadth < .55:
        for s in ("XAU", "US10Y", "CN10Y"):
            vals[ENSEMBLE[5][0]][s] = 0.0
    score = {s: 0.0 for s in UNIVERSE}
    for fid, weight, direction in ENSEMBLE:
        rr = rank(vals[fid])
        for s in UNIVERSE:
            score[s] += weight * direction * rr[s]
    if breadth < .55:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .10
    floor = min(score.values())
    target = bounded({s: score[s] - floor + .05 for s in UNIVERSE})
    mean, sd = np.mean(list(score.values())), max(np.std(list(score.values())), 1e-8)
    forecast = {s: float(.006 * (score[s] - mean) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in ENSEMBLE], horizon_days=10)
    last_decision = end

