import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ENSEMBLE = [
    ("miner_3_defensive_volatility_quality_10d", 0.22, 1),
    ("miner_1_volatility_compression_10d_v1", 0.16, 1),
    ("miner_2_20301114_market_residual_reversal_20d", 0.18, 1),
    ("relative_lowvolatility_10d", 0.12, 1),
    ("miner_1_volscaled_momentum20_10d", 0.16, 1),
    ("miner_1_residual_momentum_quality_10d", 0.08, 1),
    ("miner_1_range_efficiency_reversal_10d_v2", 0.08, 1),
]
last_decision = -10**9


def ranks(values):
    good = sorted(v for v in values.values() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for s, v in values.items():
            if np.isfinite(v):
                out[s] = np.searchsorted(good, v, side="right") / len(good)
    return out


def bounded(raw):
    # Full investment with sensible 15-asset concentration limits.
    w = {s: max(float(raw.get(s, 0.05)), 1e-8) for s in UNIVERSE}
    for _ in range(40):
        z = sum(w.values())
        w = {s: v / z for s, v in w.items()}
        low = [s for s in UNIVERSE if w[s] < 0.02]
        high = [s for s in UNIVERSE if w[s] > 0.15]
        if not low and not high:
            break
        fixed = {s: 0.02 for s in low}
        fixed.update({s: 0.15 for s in high})
        free = [s for s in UNIVERSE if s not in fixed]
        old = w
        remaining = 1.0 - sum(fixed.values())
        denom = sum(old[s] for s in free)
        w = dict(fixed)
        for s in free:
            w[s] = remaining * old[s] / max(denom, 1e-12)
    z = sum(w.values())
    return {s: max(0.0, w[s] / z) for s in UNIVERSE}


@register_hook
def strategy():
    global last_decision
    closes = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=340)
        if df is None or len(df) < 270:
            continue
        c = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(c) >= 270 and np.all(np.isfinite(c)) and np.all(c > 0):
            closes[symbol] = c
    if len(closes) < 10:
        return
    end = min(len(c) for c in closes.values()) - 2  # lag one completed session
    if end < 260 or end - last_decision < 10:
        return

    logret = {s: np.diff(np.log(c)) for s, c in closes.items()}
    r10 = {s: x[end-10:end].sum() for s, x in logret.items()}
    r20 = {s: x[end-20:end].sum() for s, x in logret.items()}
    vol10 = {s: max(np.std(x[end-10:end]), 0.008) for s, x in logret.items()}
    vol20 = {s: max(np.std(x[end-20:end]), 0.008) for s, x in logret.items()}
    med10 = float(np.median(list(r10.values())))
    med20 = float(np.median(list(r20.values())))
    medvol = max(float(np.median(list(vol20.values()))), 0.008)
    values = {f: {} for f, _, _ in ENSEMBLE}

    for s, x in logret.items():
        prior = max(np.std(x[end-30:end-10]), 0.008)
        longvol = max(np.std(x[end-40:end]), 0.008)
        hist = [np.std(x[j-20:j]) for j in range(max(20, end-120), end)]
        histmed = max(float(np.median(hist)), 0.008)
        abs10 = max(np.sum(np.abs(x[end-10:end])), 0.008)
        abs20 = max(np.sum(np.abs(x[end-20:end])), 0.008)
        values["miner_3_defensive_volatility_quality_10d"][s] = -(vol20[s] / histmed) - 0.5 * (vol20[s] / prior - 1)
        values["miner_1_volatility_compression_10d_v1"][s] = -(vol10[s] / longvol - 1)
        values["miner_2_20301114_market_residual_reversal_20d"][s] = -(r20[s] - med20) / vol20[s]
        values["relative_lowvolatility_10d"][s] = -np.log(vol20[s] / medvol)
        values["miner_1_volscaled_momentum20_10d"][s] = r20[s] / abs20
        values["miner_1_residual_momentum_quality_10d"][s] = r10[s] / vol10[s]
        values["miner_1_range_efficiency_reversal_10d_v2"][s] = -(abs10 - abs(r10[s])) / abs10

    score = {s: 0.0 for s in UNIVERSE}
    for factor, weight, direction in ENSEMBLE:
        rr = ranks(values[factor])
        for s in UNIVERSE:
            score[s] += weight * direction * rr[s]

    # In a high-risk, weak-breadth tape, use tradable defensive assets, never cash.
    breadth = np.mean([x[end-60:end].sum() > 0 for x in logret.values()])
    if breadth < 0.45:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.10

    floor = min(score.values())
    target = bounded({s: score[s] - floor + 0.05 for s in UNIVERSE})
    avg = float(np.mean(list(score.values())))
    scale = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(0.006 * (score[s] - avg) / scale) for s in UNIVERSE}
    rebalance_to_weights(
        target,
        forecast_returns=forecast,
        factor_ids=[f for f, _, _ in ENSEMBLE],
        horizon_days=10,
    )
    last_decision = end

