import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Exact current Screener ensemble: ids, weights, and directions are preserved.
ENSEMBLE = [
    ("miner_1_volatility_compression_10d_v1", 0.24, 1),
    ("miner_3_defensive_volatility_quality_10d", 0.24, 1),
    ("miner_2_20301114_market_residual_reversal_20d", 0.14, 1),
    ("relative_lowvolatility_10d", 0.14, 1),
    ("relative_residual_reversal_10d", 0.10, 1),
    ("miner_1_volume_confirmed_momentum20_10d", 0.08, 1),
    ("miner_1_consistency_volscaled_momentum20_10d", 0.06, 1),
]
last_decision = -10**9

def ranks(values):
    good = sorted(v for v in values.values() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for s, v in values.items():
            if np.isfinite(v):
                out[s] = np.searchsorted(good, v, side="right") / len(good)
    return out

def bounded(raw):
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    for _ in range(60):
        z = sum(w.values())
        q = {s: v / z for s, v in w.items()}
        fixed = {s: (0.02 if q[s] < 0.02 else 0.15)
                 for s in UNIVERSE if q[s] < 0.02 or q[s] > 0.15}
        if not fixed:
            return q
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(fixed.values())
        denom = sum(q[s] for s in free)
        w = dict(fixed)
        for s in free:
            w[s] = rem * q[s] / max(denom, 1e-12)
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}

@register_hook
def strategy():
    global last_decision
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=340)
        if df is None or len(df) < 270:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float)
        vol = np.asarray(df["volume"], float) if "volume" in df else np.ones(len(c))
        if np.all(np.isfinite(c)) and np.all(c > 0):
            data[s] = (c, vol)
    if len(data) < 10:
        return
    end = min(len(v[0]) for v in data.values()) - 2
    if end < 260 or end - last_decision < 10:
        return
    ret = {s: np.diff(np.log(v[0])) for s, v in data.items()}
    r10 = {s: x[end-10:end].sum() for s, x in ret.items()}
    r20 = {s: x[end-20:end].sum() for s, x in ret.items()}
    r60 = {s: x[end-60:end].sum() for s, x in ret.items()}
    v10 = {s: max(np.std(x[end-10:end]), .008) for s, x in ret.items()}
    v20 = {s: max(np.std(x[end-20:end]), .008) for s, x in ret.items()}
    med20 = max(float(np.median(list(v20.values()))), .008)
    market20 = float(np.median(list(r20.values())))
    median10 = float(np.median(list(r10.values())))
    breadth = float(np.mean([r20[s] > 0 for s in ret]))
    vals = {f: {} for f, _, _ in ENSEMBLE}
    for s, x in ret.items():
        c, volume = data[s]
        prior = max(np.std(x[end-30:end-10]), .008)
        longv = max(np.std(x[end-60:end]), .008)
        histv = [np.std(x[j-10:j]) for j in range(max(10, end-100), end)]
        hmed = max(float(np.median(histv)), .008)
        lv = np.log(np.maximum(volume, 1e-12))
        vs = (lv[end-20:end].mean() - lv[max(0, end-80):end-20].mean()) if len(lv) >= 80 else 0.0
        vs = float(np.clip(vs, -2, 2))
        vals["miner_1_volatility_compression_10d_v1"][s] = -(v10[s] / longv - 1)
        vals["miner_3_defensive_volatility_quality_10d"][s] = -(v20[s] / hmed) - .5 * (v20[s] / prior - 1)
        vals["miner_2_20301114_market_residual_reversal_20d"][s] = -(r20[s] - market20) / v20[s]
        vals["relative_lowvolatility_10d"][s] = -np.log(v20[s] / med20)
        vals["relative_residual_reversal_10d"][s] = -(r10[s] - median10) / v10[s]
        vals["miner_1_volume_confirmed_momentum20_10d"][s] = r20[s] * (1 + .25 * vs)
        vals["miner_1_consistency_volscaled_momentum20_10d"][s] = r20[s] / max(np.sum(np.abs(x[end-20:end])), .008)
    score = {s: 0.0 for s in UNIVERSE}
    for f, wt, direction in ENSEMBLE:
        rr = ranks(vals[f])
        for s in UNIVERSE:
            score[s] += wt * direction * rr[s]
    # High-risk narrow conditions tilt only among tradable defensive assets; no cash sleeve.
    if np.mean([r60[s] > 0 for s in ret]) < .45 or breadth < .40:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .08
    floor = min(score.values())
    target = bounded({s: score[s] - floor + .05 for s in UNIVERSE})
    avg = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-8)
    forecast = {s: float(.006 * (score[s] - avg) / sd) for s in UNIVERSE}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f for f, _, _ in ENSEMBLE], horizon_days=10)
    last_decision = end

