# Exact current Screener ensemble (7 active factors; all directions are positive).
ENSEMBLE = [
    ("miner_3_20300613_relative_residual_reversal_10d", 0.255, 1),
    ("miner_2_20301114_market_residual_reversal_20d", 0.183, 1),
    ("miner_1_20300307_volatility_compression_10d", 0.173, 1),
    ("miner_3_defensive_volatility_quality_10d", 0.144, 1),
    ("miner_1_20301226_volume_confirmed_momentum20_10d", 0.103, 1),
    ("miner_3_20300711_relative_lowvolatility_10d", 0.087, 1),
    ("miner_2_20300124_lowvolatility_10d", 0.055, 1),
]
last_decision = -10**9

def rank(values):
    good = sorted(float(v) for v in values.values() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if len(good) > 1:
        for s, v in values.items():
            if np.isfinite(v):
                out[s] = np.searchsorted(good, v, side="right") / len(good)
    return out

@register_hook
def strategy():
    global last_decision
    series = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=340)
        if df is None or len(df) < 270:
            continue
        df = df.sort_values("date")
        close = np.asarray(df["close"], dtype=float)
        volume = np.asarray(df["volume"], dtype=float) if "volume" in df else np.ones(len(close))
        if len(close) >= 270 and np.all(np.isfinite(close)) and np.all(close > 0):
            series[s] = (np.diff(np.log(close)), volume)
    if len(series) < 10:
        return
    end = min(len(v[0]) for v in series.values()) - 1
    if end < 260 or end - last_decision < 10:
        return
