UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Exact active Screener ensemble (IDs, weights, directions).
ENSEMBLE = [
    ("miner_3_defensive_volatility_quality_10d", 0.25, 1),
    ("miner_2_20300124_lowvolatility_10d", 0.18, 1),
    ("relative_lowvolatility_10d", 0.15, 1),
    ("trend_inefficiency_reversal_10d", 0.12, 1),
    ("relative_residual_reversal_10d", 0.10, 1),
    ("miner_2_20301114_market_residual_reversal_20d", 0.10, 1),
    ("miner_1_volume_confirmed_momentum20_10d", 0.05, 1),
    ("miner_3_tailrisk_reversal_10d", 0.05, 1),
]
last_decision = -10**9

def pct_rank(x):
    good = np.asarray([v for v in x.values() if np.isfinite(v)], float)
    out = {s: .5 for s in UNIVERSE}
    if len(good) > 1:
        for s, v in x.items():
            if np.isfinite(v):
                out[s] = float(np.mean(good <= v))
    return out

def safe_std(x):
    return max(float(np.std(x)), .008)

@register_hook
def strategy():
    global last_decision
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=360)
        if df is None or len(df) < 280:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        vol = np.asarray(df["volume"], dtype=float) if "volume" in df else np.ones(len(c))
        if np.all(np.isfinite(c)) and np.all(c > 0):
            data[s] = (np.diff(np.log(c)), vol)
    if len(data) < 10:
        return
    t = min(len(v[0]) for v in data.values()) - 1
    if t < 270 or t - last_decision < 10:
        return
    ret = {s: v[0] for s, v in data.items()}
    r10 = {s: x[t-10:t].sum() for s, x in ret.items()}
    r20 = {s: x[t-20:t].sum() for s, x in ret.items()}
    v10 = {s: safe_std(x[t-10:t]) for s, x in ret.items()}
    v20 = {s: safe_std(x[t-20:t]) for s, x in ret.items()}
    med10, med20, medr20 = np.median(list(v10.values())), np.median(list(v20.values())), np.median(list(r20.values()))
    signals = {f: {} for f, _, _ in ENSEMBLE}
    market = np.mean(np.array([x[t-60:t] for x in ret.values()]), axis=0)
    for s, x in ret.items():
        hist = [safe_std(x[j-10:j]) for j in range(max(20, t-120), t-10)]
