    # Bear regime: retain full investment but favor defensive tradable assets.
    breadth = np.mean([r20[s] > 0 for s in ret])
    if breadth < .45:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += .08
    z = np.array([score[s] for s in UNIVERSE], float)
    z = np.clip((z - z.mean()) / max(z.std(), 1e-8), -2, 2)
    ew = np.exp(.65 * z); ew /= ew.sum()
    target = {s: float(.70 * ew[i] + .30 / len(UNIVERSE)) for i, s in enumerate(UNIVERSE)}
