    return {s: (float(np.mean(np.asarray(finite) <= v)) if np.isfinite(v) else 0.5)
            for s, v in values.items()}


def safe_vol(x):
    return max(float(np.std(x)), 0.008)


@register_hook
def strategy():
    global _days_since_rebalance
    _days_since_rebalance += 1
