              for i, s in enumerate(UNIVERSE)}
    # Deterministic forecast for every tradable asset, required by migration gate.
    forecast = {s: float(0.006 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[f for f, _, _ in ENSEMBLE], horizon_days=10)
    _days_since_rebalance = 0

