        q = r[-20:]
        return (np.sum(q) / v20) * (0.5 + np.mean(q > 0))
    if "risk_adjusted_breadth_momentum" in fid:
        q = r[-10:]
        return np.sum(q) / v10 * (0.5 + np.mean(q > 0))
