import json
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
with open("factors/factor_ensemble.json", encoding="utf-8") as f:
    _selected = json.load(f).get("selected_factors", [])[:10]
ENSEMBLE = [(x["factor_id"], float(x["weight"]), int(x["direction"])) for x in _selected]
_day = 0


def vol(x, n):
    return max(float(np.std(x[-n:])), 1e-8)


def rank_signal(values):
    a = np.array([values.get(s, np.nan) for s in UNIVERSE], dtype=float)
    valid = a[np.isfinite(a)]
    a[~np.isfinite(a)] = float(np.median(valid)) if len(valid) else 0.0
    order = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort")
    den = max(len(UNIVERSE) - 1, 1)
    return {s: float(order[i] / den - 0.5) for i, s in enumerate(UNIVERSE)}


def factor_signal(fid, r, market):
    v10, v20 = vol(r, 10), vol(r, 20)
    if "defensive_volatility_quality" in fid:
        downside = np.sqrt(np.mean(np.minimum(r[-40:], 0.0) ** 2))
        return -(v20 + 0.25 * downside)
    if "relative_lowvolatility" in fid:
        return -v20
    if "volatility_compression" in fid:
        return -v10 / vol(r[:-10], 10) - 0.15 * v20
    if "market_residual_reversal" in fid or "dispersion_gated_downside_reversal" in fid:
        beta = np.cov(r[-60:], market[-60:])[0, 1] / max(np.var(market[-60:]), 1e-8)
        residual = np.sum(r[-20:]) - beta * np.sum(market[-20:])
        # Dispersion gate reduces reversal exposure when the cross-section is quiet.
        gate = np.std(np.array([x[-20:].sum() for x in RETURNS.values()]))
        return -residual / v20 * (1.0 if gate >= np.median(DISPERSIONS) else 0.5)
    if "drawdown_convex_reversal" in fid:
        path = np.exp(np.cumsum(r[-60:]))
        dd = path / np.maximum.accumulate(path) - 1.0
        return -float(dd[-1]) / v20
    if "consistency_volscaled_momentum" in fid:
        q = r[-20:]
        return np.sum(q) / v20 * (0.5 + np.mean(q > 0))
    return 0.0


@register_hook
def strategy():
    global _day, RETURNS, DISPERSIONS
    _day += 1
    if _day < 10 or not ENSEMBLE:
        return
    closes = {}
    for s in UNIVERSE:
