with open("factor_ensemble.json", encoding="utf-8") as f:
    _raw = json.load(f).get("selected_factors", [])
ENSEMBLE = [(x["factor_id"], float(x["weight"]), int(x["direction"])) for x in _raw[:10]]
_day = 0


def _rank(vals):
    a = np.array([vals.get(s, np.nan) for s in UNIVERSE], dtype=float)
    good = a[np.isfinite(a)]
    fill = float(np.median(good)) if len(good) else 0.0
    a[~np.isfinite(a)] = fill
    ranks = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort")
    return {s: float(ranks[i] / 14.0 - 0.5) for i, s in enumerate(UNIVERSE)}


def _sd(x, n):
    return max(float(np.std(x[-n:])), 1e-8)


def _signal(fid, r, market, cross_disp):
    v10, v20 = _sd(r, 10), _sd(r, 20)
    if fid == "miner_3_defensive_volatility_quality_10d":
        down = np.sqrt(np.mean(np.minimum(r[-40:], 0.0) ** 2))
        return -(v20 + 0.25 * down)
    if fid == "miner_1_volatility_compression_10d_v1":
        return -v10 / _sd(r[:-10], 10) - 0.15 * v20
    if fid == "relative_lowvolatility_10d":
        return -v20
    if fid == "miner_2_20301114_market_residual_reversal_20d":
        beta = np.cov(r[-60:], market[-60:])[0, 1] / max(np.var(market[-60:]), 1e-8)
        residual = np.sum(r[-20:]) - beta * np.sum(market[-20:])
        return -residual / v20 * (1.0 if cross_disp >= 0.01 else 0.5)
    if fid == "miner_1_20330203_drawdown_convex_reversal_10d":
        path = np.exp(np.cumsum(r[-60:]))
        dd = path / np.maximum.accumulate(path) - 1.0
        return -float(dd[-1]) / v20
    if fid == "miner_1_consistency_volscaled_momentum20_10d":
        q = r[-20:]
        return np.sum(q) / v20 * (0.5 + np.mean(q > 0))
    return 0.0


@register_hook
def strategy():
    global _day
    _day += 1
    if _day < 10 or not ENSEMBLE:
        return
    closes = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=360)
        if df is None or len(df) < 130:
            continue
        x = np.asarray(df.sort_values("date")["close"], dtype=float)
        if np.all(np.isfinite(x)) and np.all(x > 0):
            closes[s] = x
    if len(closes) < 10:
        _day = 0
        return
    n = min(len(x) for x in closes.values())
    returns = {s: np.diff(np.log(x[-n:])) for s, x in closes.items()}
    market = np.mean(np.array(list(returns.values())), axis=0)
    cross_disp = float(np.std([np.sum(r[-20:]) for r in returns.values()]))
    scores = {s: 0.0 for s in UNIVERSE}
    for fid, weight, direction in ENSEMBLE:
        raw = {s: np.clip(_signal(fid, r, market, cross_disp), -10, 10) for s, r in returns.items()}
        ranked = _rank(raw)
        for s in UNIVERSE:
            scores[s] += weight * direction * ranked[s]
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in returns.values()]))
    stressed = breadth < 0.45
    vix = get_index_daily_data(symbol="VIX", days=30)
    if vix is not None and len(vix) >= 21:
        vx = np.asarray(vix.sort_values("date")["close"], dtype=float)
        stressed = stressed or bool(np.isfinite(vx[-1]) and vx[-1] > 1.10 * np.median(vx[-21:]))
    if stressed:
        for s, bonus in (("XAU", 0.12), ("US10Y", 0.07), ("CN10Y", 0.05)):
            scores[s] += bonus
        for s in ("WTI", "BTC", "ETH"):
            scores[s] -= 0.035
    z = np.array([scores[s] for s in UNIVERSE], dtype=float)
    z = np.clip((z - z.mean()) / max(z.std(), 1e-8), -1.4, 1.4)
    p = np.exp(0.30 * z)
    p /= p.sum()
    target = {s: float(0.55 * p[i] + 0.45 / 15.0) for i, s in enumerate(UNIVERSE)}
    forecast = {s: float(0.0025 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in ENSEMBLE], horizon_days=10)
    _day = 0"}

