import json
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
with open("factor_ensemble.json", encoding="utf-8") as f:
    _raw = json.load(f).get("selected_factors", [])[:10]
ENSEMBLE = [(str(x["factor_id"]), float(x["weight"]), int(x["direction"])) for x in _raw]
_day = 0


def _rank(values):
    a = np.array([values.get(s, np.nan) for s in UNIVERSE], dtype=float)
    good = a[np.isfinite(a)]
    fill = float(np.median(good)) if len(good) else 0.0
    a[~np.isfinite(a)] = fill
    order = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort")
    return {s: float(order[i] / 14.0 - 0.5) for i, s in enumerate(UNIVERSE)}


def _vol(r, n):
    return max(float(np.std(r[-n:])), 1e-8)


def _signal(fid, r, all_r):
    # Inputs end at the last completed session; lag once for the factor signal.
    q = r[:-1]
    if len(q) < 65:
        return 0.0
    v20 = _vol(q, 20)
    cross_v20 = np.array([_vol(x[:-1], 20) for x in all_r.values() if len(x) >= 66])
    medv = max(float(np.median(cross_v20)), 1e-8)
    if fid == "miner_3_defensive_volatility_quality_10d":
        old = _vol(q[:-10], 20)
        return -(v20 / medv) - 0.5 * (v20 / old - 1.0)
    if fid == "relative_lowvolatility_10d":
        return -np.log(max(v20 / medv, 1e-8))
    if fid == "miner_1_20330203_drawdown_convex_reversal_10d":
        ret60 = float(np.sum(q[-60:]))
        peak = max(float(np.max(np.cumsum(q[-120:]))), 0.0)
        drawdown = abs(min(float(np.sum(q[-120:]) - peak), 0.0))
        consistency = float(np.mean(q[-60:] > 0))
        return (-ret60 / (_vol(q, 60) * np.sqrt(60))) * (1.0 + 2.0 * drawdown) * (0.5 + consistency)
    if fid == "miner_1_consistency_volscaled_momentum20_10d":
        return (float(np.sum(q[-20:])) / (_vol(q, 20) * np.sqrt(20))) * (0.5 + float(np.mean(q[-20:] > 0)))
    if fid == "miner_1_volatility_compression_10d_v1":
        return -(_vol(q, 10) / _vol(q, 40) - 1.0)
    return 0.0


@register_hook
def strategy():
    global _day
    _day += 1
    if _day < 10 or not ENSEMBLE:
        return
    closes = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=360)
        if df is None or len(df) < 140:
            continue
        x = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(x) >= 140 and np.all(np.isfinite(x)) and np.all(x > 0):
            closes[s] = x
    if len(closes) < 10:
        _day = 0
        return
    n = min(len(x) for x in closes.values())
    returns = {s: np.diff(np.log(x[-n:])) for s, x in closes.items()}
    scores = {s: 0.0 for s in UNIVERSE}
    for fid, weight, direction in ENSEMBLE:
        raw = {s: _signal(fid, r, returns) for s, r in returns.items()}
        ranked = _rank(raw)
        for s in UNIVERSE:
            scores[s] += weight * direction * ranked[s]
    # Medium-high risk overlay: full investment, with only tradable defensives.
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in returns.values()]))
    stressed = breadth < 0.45
    if stressed:
        for s, boost in (("XAU", 0.12), ("US10Y", 0.07), ("CN10Y", 0.05)):
            scores[s] += boost
        for s in ("WTI", "BTC", "ETH"):
            scores[s] -= 0.035
    z = np.array([scores[s] for s in UNIVERSE], dtype=float)
