def _sd(x, n):
    return max(float(np.std(x[-n:])), 1e-8)


def _signal(fid, r, all_r):
    q = r[:-1]  # one-session lag: no use of the current incomplete session
    if len(q) < 65:
        return 0.0
    v10, v20, v40 = _sd(q, 10), _sd(q, 20), _sd(q, 40)
    cross = [_sd(x[:-1], 20) for x in all_r.values() if len(x) >= 66]
    med = max(float(np.median(cross)), 1e-8)
    if fid == "miner_1_volatility_compression_10d_v1":
        return -(v10 / v40 - 1.0)
    if fid == "miner_3_defensive_volatility_quality_10d":
        return -(v20 / med) - 0.5 * (v20 / max(_sd(q[:-10], 20), 1e-8) - 1.0)
    if fid == "relative_lowvolatility_10d":
        return -np.log(max(v20 / med, 1e-8))
    if fid == "miner_1_consistency_volscaled_momentum20_10d":
        return (float(np.sum(q[-20:])) / (v20 * np.sqrt(20))) * (0.5 + float(np.mean(q[-20:] > 0)))
    if fid == "miner_2_20301114_market_residual_reversal_20d":
        # Residual reversal against the equal-weight universe return.
        m = np.mean([x[-20:] for x in all_r.values() if len(x) >= 20], axis=0)
        residual = q[-20:] - m
        return -float(np.sum(residual)) / (v20 * np.sqrt(20))
    if fid == "miner_1_20330203_drawdown_convex_reversal_10d":
        ret60 = float(np.sum(q[-60:]))
        path = np.cumsum(q[-120:])
        dd = abs(min(float(np.sum(q[-120:]) - np.max(path)), 0.0))
        return (-ret60 / (_sd(q, 60) * np.sqrt(60))) * (1.0 + 2.0 * dd) * (0.5 + float(np.mean(q[-60:] > 0)))
    return 0.0


