    scores = {s: 0.0 for s in UNIVERSE}
    for fid, weight, direction in ENSEMBLE:
        ranked = _rank({s: _signal(fid, r, returns) for s, r in returns.items()})
        for s in UNIVERSE:
            scores[s] += weight * direction * ranked[s]
    breadth = float(np.mean([np.mean(r[-20:] > 0) for r in returns.values()]))
    if breadth < 0.45:
        for s, boost in (("XAU", 0.12), ("US10Y", 0.07), ("CN10Y", 0.05)):
            scores[s] += boost
        for s in ("WTI", "BTC", "ETH"):
            scores[s] -= 0.035
    z = np.array([scores[s] for s in UNIVERSE], dtype=float)
    z = np.clip((z - np.mean(z)) / max(float(np.std(z)), 1e-8), -1.4, 1.4)
    p = np.exp(0.30 * z); p /= np.sum(p)
    target = {s: float(0.55 * p[i] + 0.45 / 15.0) for i, s in enumerate(UNIVERSE)}
    forecast = {s: float(0.0025 * z[i]) for i, s in enumerate(UNIVERSE)}
    # Complete, long-only target and deterministic 10-session forecast are mandatory.
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[x[0] for x in ENSEMBLE], horizon_days=10)
    _day = 0

