with open("factor_ensemble.json", encoding="utf-8") as f:
    _raw = json.load(f).get("selected_factors", [])[:10]
ENSEMBLE = [(str(x["factor_id"]), float(x["weight"]), int(x.get("direction", 1))) for x in _raw]
_day = 0


def _rank(values):
    a = np.array([values.get(s, np.nan) for s in UNIVERSE], dtype=float)
    good = a[np.isfinite(a)]
    fill = float(np.median(good)) if len(good) else 0.0
    a[~np.isfinite(a)] = fill
    order = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort")
    return {s: float(order[i] / 14.0 - 0.5) for i, s in enumerate(UNIVERSE)}


def _vol(x, n):
    return max(float(np.std(x[-n:])), 1e-8)


def _signal(fid, r, panel):
    # All observations are lagged by one completed session.
    q = r[:-1]
    if len(q) < 65:
        return 0.0
    v10, v20, v40 = _vol(q, 10), _vol(q, 20), _vol(q, 40)
    peer20 = [_vol(x[:-1], 20) for x in panel.values() if len(x) >= 66]
    med = max(float(np.median(peer20)), 1e-8)
    if fid == "miner_1_20300307_volatility_compression_10d":
        return -(v10 / v40 - 1.0)
    if fid == "miner_3_defensive_volatility_quality_10d":
        # Low recent volatility, with a penalty for volatility expansion.
        prior = _vol(q[:-10], 20)
        return -(v20 / med) - 0.5 * (v20 / prior - 1.0)
    if fid == "relative_lowvolatility_10d":
        return -np.log(max(v20 / med, 1e-8))
    if fid == "miner_1_20301128_consistency_volscaled_momentum20_10d":
        return (float(np.sum(q[-20:])) / (v20 * np.sqrt(20))) * (0.5 + float(np.mean(q[-20:] > 0)))
