def rank(v):
    a = np.array([v.get(s, np.nan) for s in UNIVERSE], float)
    good = a[np.isfinite(a)]
    a[~np.isfinite(a)] = np.median(good) if len(good) else 0.0
    order = np.argsort(np.argsort(a, kind="mergesort"), kind="mergesort")
    return {s: float(order[i] / 14.0 - .5) for i, s in enumerate(UNIVERSE)}

def vol(x, n):
    return max(float(np.std(x[-n:])), 1e-8)

def signal(fid, q, panel):
    if len(q) < 65: return 0.0
    v10, v20, v40 = vol(q, 10), vol(q, 20), vol(q, 40)
    peer = [vol(x, 20) for x in panel.values() if len(x) >= 65]
    med = max(float(np.median(peer)), 1e-8)
    if "defensive_volatility_quality" in fid:
        return -v20 / med
    if "volatility_compression" in fid:
        return -(v10 / v40 - 1.0)
    if "relative_lowvolatility" in fid:
        return -np.log(max(v20 / med, 1e-8))
    if "consistency_volscaled_momentum20" in fid:
        return float(np.sum(q[-20:]) / (v20 * np.sqrt(20))) * (0.5 + float(np.mean(q[-20:] > 0)))
    if "market_residual_reversal" in fid:
        common = np.mean(np.array([x[-20:] for x in panel.values() if len(x) >= 20]), axis=0)
        resid = q[-20:] - common
        return -float(np.sum(resid)) / (vol(resid, 20) * np.sqrt(20))
    if "drawdown_convex_reversal" in fid:
        return -float(np.sum(q[-60:])) / (vol(q, 60) * np.sqrt(60))
